#!/usr/bin/env bash
# metallb/metallb 0.16.1 - base variant: default
# Path: fetch this entry's retained objects, check their SHA-256, then apply
# them with kubectl. It uses curl, shasum, awk and kubectl. It needs no cub
# CLI and no ConfigHub account.
# Generated by scripts/generate-public-site.mjs from this entry's listing:
# https://confighub.github.io/helm-expt/site/listings/metallb-metallb-0-16-1-default.json
# Entry page: https://confighub.github.io/helm-expt/site/charts/metallb-metallb-0-16-1.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

for tool in curl awk kubectl; do
  if ! command -v "$tool" >/dev/null 2>&1; then
    printf '%s is required and was not found.\n' "$tool" >&2
    exit 1
  fi
done
if command -v shasum >/dev/null 2>&1; then
  sha256_of() { shasum -a 256 "$1" | awk '{print $1}'; }
elif command -v sha256sum >/dev/null 2>&1; then
  sha256_of() { sha256sum "$1" | awk '{print $1}'; }
else
  printf 'shasum is required and was not found.\n' >&2
  exit 1
fi

work=./metallb-metallb-0-16-1-default-objects
objects_url=https://raw.githubusercontent.com/confighub/helm-expt/main/recipes/metallb/metallb/0.16.1/revisions/default/r001/rendered/release-objects.yaml
objects_sha256=430fb6a1ec84cd0b737106c4b87ac33d9734adb9fd337767a3161c90d7ae2d4e

say "Fetch the retained objects into $work/objects.yaml"
mkdir -p "$work"
curl -fsSL -o "$work/objects.yaml" "$objects_url"

say "Check the file against the SHA-256 in the listing"
fetched_sha256="$(sha256_of "$work/objects.yaml")"
if [ "$fetched_sha256" != "$objects_sha256" ]; then
  printf 'The file differs from the listing, so the script stops. Nothing was applied.\n  listing: %s\n  fetched: %s\n' "$objects_sha256" "$fetched_sha256" >&2
  exit 1
fi
printf 'The file matches: sha256 %s\n' "$fetched_sha256"

say "Split the file into its 42 objects. The cluster is untouched so far"
rm -rf "$work/docs" "$work/crds" "$work/rest"
mkdir -p "$work/docs" "$work/crds" "$work/rest"
awk -v dir="$work/docs" 'BEGIN { n = 0; f = sprintf("%s/doc-%04d.yaml", dir, n) } /^---[ \t]*$/ { close(f); n++; f = sprintf("%s/doc-%04d.yaml", dir, n); next } { print > f }' "$work/objects.yaml"
for n in 0008 0009 0010 0011 0012 0013 0014 0015 0016 0017 0018 0019; do mv "$work/docs/doc-$n.yaml" "$work/crds/"; done
for n in 0020; do mv "$work/docs/doc-$n.yaml" "$work/crds/"; done
for n in 0001 0002 0003 0004 0005 0006 0007 0021 0022 0023 0024 0025; do mv "$work/docs/doc-$n.yaml" "$work/rest/"; done
for n in 0026 0027 0028 0029 0030 0031 0032 0033 0034 0035 0036 0037; do mv "$work/docs/doc-$n.yaml" "$work/rest/"; done
for n in 0038 0039 0040 0041 0042; do mv "$work/docs/doc-$n.yaml" "$work/rest/"; done
ls "$work/crds" "$work/rest"

say "Check that kubectl reaches a cluster"
if ! kubectl get --raw /version >/dev/null 2>&1; then
  printf 'kubectl cannot reach a cluster. Point it at a throwaway cluster and re-run this script.\n' >&2
  exit 1
fi
kubectl config current-context 2>/dev/null || true

say "Create the metallb-system namespace if it does not exist"
if ! kubectl get namespace metallb-system >/dev/null 2>&1; then
  kubectl create namespace metallb-system
fi

wait_for_crd() {
  crd_name="$1"
  deadline=$(( $(date +%s) + 180 ))
  until kubectl get "crd/${crd_name}" >/dev/null 2>&1; do
    if [ "$(date +%s)" -ge "$deadline" ]; then
      printf "CRD %s did not appear within 180 seconds.\n" "$crd_name" >&2
      return 1
    fi
    sleep 2
  done
  kubectl wait --for=condition=Established --timeout=120s "crd/${crd_name}"
}

say "Check the 13 CRDs this file holds"
missing_crds=0
if ! kubectl get crd/bfdprofiles.metallb.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/bgpadvertisements.metallb.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/bgppeers.metallb.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/communities.metallb.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/configurationstates.metallb.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/ipaddresspools.metallb.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/l2advertisements.metallb.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/servicebgpstatuses.metallb.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/servicel2statuses.metallb.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/bgpsessionstates.frrk8s.metallb.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/frrconfigurations.frrk8s.metallb.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/frrk8sconfigurations.frrk8s.metallb.io >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/frrnodestates.frrk8s.metallb.io >/dev/null 2>&1; then
  missing_crds=1
fi
if [ "$missing_crds" -eq 1 ]; then
  say "A CRD is missing, so apply the file's CRDs first"
  kubectl apply --server-side -f "$work/crds"
  crd_outcome="were applied first"
elif kubectl diff --server-side -f "$work/crds" >/dev/null 2>&1; then
  say "The CRDs already exist and match this file. The script leaves them under their current owner"
  crd_outcome="already existed and matched, so the script left them alone"
elif [ "${APPLY_CRDS:-0}" = "1" ]; then
  say "The existing CRDs differ from this file. APPLY_CRDS=1 is set, so the script applies the file's CRDs"
  kubectl apply --server-side -f "$work/crds"
  crd_outcome="differed and were applied, because APPLY_CRDS=1 was set"
else
  say "The CRDs already exist and differ from this file, or another tool owns them"
  cat <<'EOF_CRDS'
This script does not change CRDs it did not just create.
If this is an upgrade, the objects that follow may need the newer CRDs.
To let this script apply the file's CRDs, re-run with:
  APPLY_CRDS=1 bash try-objects.sh
EOF_CRDS
  exit 1
fi
wait_for_crd bfdprofiles.metallb.io
wait_for_crd bgpadvertisements.metallb.io
wait_for_crd bgppeers.metallb.io
wait_for_crd communities.metallb.io
wait_for_crd configurationstates.metallb.io
wait_for_crd ipaddresspools.metallb.io
wait_for_crd l2advertisements.metallb.io
wait_for_crd servicebgpstatuses.metallb.io
wait_for_crd servicel2statuses.metallb.io
wait_for_crd bgpsessionstates.frrk8s.metallb.io
wait_for_crd frrconfigurations.frrk8s.metallb.io
wait_for_crd frrk8sconfigurations.frrk8s.metallb.io
wait_for_crd frrnodestates.frrk8s.metallb.io

say "Apply the other 29 objects"
kubectl apply -f "$work/rest"

say "Done. The 13 CRDs $crd_outcome. kubectl applied the other 29 objects of this entry's retained file."
say "The script stops here. It did not wait for any workload to start"
